import json
import os
from orca_task_sdk import run_orca

rec = run_orca(
    "job.inp",
    dependencies=("ethanol.xyz",),
    request_key="ethanol_optfreq_repair",
)
files = rec["files"]
keys = list(files.keys())

geom_key = None
for cand in ("job.xyz",):
    if cand in files:
        geom_key = cand
        break
if geom_key is None:
    for k in keys:
        lk = k.lower()
        if lk.endswith(".xyz") and lk != "ethanol.xyz" and "input" not in lk:
            geom_key = k
            break
if geom_key is None:
    raise RuntimeError("no optimized geometry file among: " + ", ".join(keys))

out_key = None
for cand in ("stdout.out", "job.out"):
    if cand in files:
        out_key = cand
        break
if out_key is None:
    raise RuntimeError("no ORCA log file among: " + ", ".join(keys))

with open(files[geom_key], "r", errors="replace") as f:
    lines = [ln.strip() for ln in f if ln.strip()]

start = 0
n = None
while start < len(lines):
    try:
        n = int(lines[start])
        break
    except ValueError:
        start += 1
if n is None:
    raise RuntimeError("no xyz atom count")

coords = []
for ln in lines[start + 2:start + 2 + n]:
    p = ln.split()
    if len(p) >= 4:
        coords.append({"element": p[0], "x": float(p[1]), "y": float(p[2]), "z": float(p[3])})
if len(coords) != n:
    raise RuntimeError("bad xyz coordinates")

freqs = []
inblock = False
with open(files[out_key], errors="replace") as f:
    for line in f:
        if "VIBRATIONAL FREQUENCIES" in line:
            inblock = True
            continue
        if inblock:
            s = line.strip()
            if s.startswith("NORMAL MODES") or s.startswith("IR SPECTRUM"):
                break
            if ":" in s and "cm**-1" in s:
                left = s.split(":", 1)[0].strip()
                if left.isdigit():
                    parts = s.split(":", 1)[1].split()
                    if parts:
                        freqs.append(float(parts[0]))
if not freqs:
    raise RuntimeError("no vibrational frequencies found in " + out_key)

obs = [
    {
        "name": "optimized_geometry",
        "value": coords,
        "unit": "angstrom",
        "sources": [{
            "internal_request_key": rec["request_key"],
            "filename": geom_key,
            "location": "final optimized geometry",
        }],
        "limitations": ["B3LYP/def2-SVP gas-phase optimization; no experimental validation."],
    },
    {
        "name": "vibrational_frequencies",
        "value": freqs,
        "unit": "cm^-1",
        "sources": [{
            "internal_request_key": rec["request_key"],
            "filename": out_key,
            "location": "VIBRATIONAL FREQUENCIES block",
        }],
        "limitations": ["Harmonic frequencies, no scaling applied, gas phase, B3LYP/def2-SVP."],
    },
]
with open("observations.json", "w") as f:
    json.dump({"version": 1, "observations": obs}, f, sort_keys=True)

