import json
import os
from orca_task_sdk import run_orca

rec = run_orca("job.inp", dependencies=("ethanol.xyz",), request_key="ethanol_optfreq_repair_v2")
files = rec["files"]
keys = sorted(files.keys())
status = rec.get("operation_status")

def read_text(path, limit=4000000):
    with open(path, errors="replace") as f:
        return f.read(limit)

def parse_freqs(text):
    freqs = []
    inblock = False
    for line in text.splitlines():
        if "VIBRATIONAL FREQUENCIES" in line:
            inblock = True
            continue
        if not inblock:
            continue
        s = line.strip()
        if s.startswith("NORMAL MODES") or s.startswith("IR SPECTRUM"):
            inblock = False
            continue
        if ":" in s and "cm**-1" in s:
            left, right = s.split(":", 1)
            if left.strip().isdigit():
                parts = right.split()
                if parts:
                    try:
                        freqs.append(float(parts[0]))
                    except ValueError:
                        pass
    return freqs

freq_key = None
freqs = []
for k in keys:
    p = files[k]
    try:
        if os.path.getsize(p) > 8000000:
            continue
        text = read_text(p)
    except OSError:
        continue
    if "VIBRATIONAL FREQUENCIES" not in text:
        continue
    got = parse_freqs(text)
    if got and len(got) > len(freqs):
        freqs = got
        freq_key = k

geom_key = None
coords = []
for k in sorted(keys, key=lambda n: (n != "job.xyz", n)):
    if not k.lower().endswith(".xyz") or k == "ethanol.xyz":
        continue
    try:
        text = read_text(files[k])
    except OSError:
        continue
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    start = None
    n = None
    for i, ln in enumerate(lines):
        try:
            n = int(ln)
        except ValueError:
            continue
        start = i
        break
    if start is None or n is None or n <= 0:
        continue
    parsed = []
    for ln in lines[start + 2:start + 2 + n]:
        p = ln.split()
        if len(p) >= 4:
            try:
                parsed.append({"element": p[0], "x": float(p[1]), "y": float(p[2]), "z": float(p[3])})
            except ValueError:
                pass
    if len(parsed) == n:
        coords = parsed
        geom_key = k
        break

if freq_key is None or geom_key is None:
    raise RuntimeError(
        "missing ORCA outputs: files=%r status=%r freqs=%r geom=%r"
        % (keys, status, freq_key, geom_key)
    )

obs = [
    {
        "name": "optimized_geometry",
        "value": coords,
        "unit": "angstrom",
        "sources": [{"internal_request_key": rec["request_key"], "filename": geom_key, "location": "final optimized geometry"}],
        "limitations": ["B3LYP/def2-SVP gas-phase optimization; no experimental validation."],
    },
    {
        "name": "vibrational_frequencies",
        "value": freqs,
        "unit": "cm^-1",
        "sources": [{"internal_request_key": rec["request_key"], "filename": freq_key, "location": "VIBRATIONAL FREQUENCIES block"}],
        "limitations": ["Harmonic frequencies, no scaling applied, gas phase, B3LYP/def2-SVP."],
    },
]
with open("observations.json", "w") as f:
    json.dump({"version": 1, "observations": obs}, f, sort_keys=True)
